preConditionHook:
// EL: highest(close, closeLookback)[1] and highest(high, highLookback)[1] --
// the two windows ENDING ONE BAR AGO, with independent lengths. Highest and
// lowest bottom out in Extremes(), EL SOURCE: seeded at the first bar of its
// window, scanning the rest with a strict, tolerance-carrying comparison, so a
// tie keeps the earliest bar. Same seed-at-[1] arrangement as
// CloseAbovePriorHighestHigh.
//
// Both windows are over price with real history, so a plain loop is right --
// no zero-filled variable mirror, no WFSafe_ accumulator.
priorHighestClose = close[1];
priorLowestClose = close[1];
for (int i = 2; i <= (int)closeLookback; ++i) {
    if (el_gt(close[i], priorHighestClose)) priorHighestClose = close[i];
    if (el_lt(close[i], priorLowestClose)) priorLowestClose = close[i];
}
priorHighestHigh = high[1];
priorLowestLow = low[1];
for (int i = 2; i <= (int)highLookback; ++i) {
    if (el_gt(high[i], priorHighestHigh)) priorHighestHigh = high[i];
    if (el_lt(low[i], priorLowestLow)) priorLowestLow = low[i];
}
